import{_ as a,o as r,c as t,ae as n}from"./chunks/framework.Cqu5Y2mC.js";const b=JSON.parse('{"title":"Protokoll Sitzung 02","description":"","frontmatter":{},"headers":[],"relativePath":"05-Gemeinsam/2026-03-20-Protokoll.md","filePath":"05-Gemeinsam/2026-03-20-Protokoll.md"}'),i={name:"05-Gemeinsam/2026-03-20-Protokoll.md"};function o(l,e,s,h,u,d){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="protokoll-sitzung-02" tabindex="-1">Protokoll Sitzung 02 <a class="header-anchor" href="#protokoll-sitzung-02" aria-label="Permalink to &quot;Protokoll Sitzung 02&quot;">​</a></h1><p><strong>Datum:</strong> 2026-03-20<br><strong>Sitzung:</strong> <em><strong>02</strong></em><br><strong>Protokollführer:</strong> <em><strong>Daniel.Saracoglu, Sofia Jäger</strong></em></p><p><strong>Teilnehmer:</strong></p><p><strong>Sybit:</strong> <em><strong>André Sommer</strong></em><br><strong>Lehrer:</strong> <em><strong>Stefan Martin, Karl Laber</strong></em><br><strong>Schüler:</strong><br><em><strong>01-Betrieb: Irakli, Marius</strong></em><br><em><strong>02-Hardware: Eray, Lukas</strong></em><br><em><strong>03-Software: Felix, Jannick, Marlon, Theodor</strong></em><br><em><strong>04-Projektleitung: Daniel, Jan, Sofia</strong></em></p><hr><h2 id="aktueller-stand-ruckblick-seit-der-letzten-sitzung" tabindex="-1">Aktueller Stand/ Rückblick seit der letzten Sitzung: <a class="header-anchor" href="#aktueller-stand-ruckblick-seit-der-letzten-sitzung" aria-label="Permalink to &quot;Aktueller Stand/ Rückblick seit der letzten Sitzung:&quot;">​</a></h2><h3 id="_1-betrieb" tabindex="-1">1. Betrieb: <a class="header-anchor" href="#_1-betrieb" aria-label="Permalink to &quot;1. Betrieb:&quot;">​</a></h3><ul><li>Das Gateway unter die Lupe genommen und geschaut wie es funktioniert.</li></ul><h3 id="_2-hardware" tabindex="-1">2. Hardware: <a class="header-anchor" href="#_2-hardware" aria-label="Permalink to &quot;2. Hardware:&quot;">​</a></h3><ul><li>Gedanken gemacht wie man den Sensor in dem Mülleimer installiert.</li></ul><h3 id="_3-software" tabindex="-1">3. Software: <a class="header-anchor" href="#_3-software" aria-label="Permalink to &quot;3. Software:&quot;">​</a></h3><ul><li>Den Server aufgesetzt und den Code vom letzten Jahr analysiert.</li></ul><h3 id="_4-projektleitung" tabindex="-1">4. Projektleitung: <a class="header-anchor" href="#_4-projektleitung" aria-label="Permalink to &quot;4. Projektleitung:&quot;">​</a></h3><ul><li>Das Protokoll hochgeladen. Mit der Stadt Singen kommuniziert.</li></ul><hr><h2 id="besprochene-themen-inhalt" tabindex="-1">Besprochene Themen/ Inhalt: <a class="header-anchor" href="#besprochene-themen-inhalt" aria-label="Permalink to &quot;Besprochene Themen/ Inhalt:&quot;">​</a></h2><h3 id="_1-thema1" tabindex="-1">1. Thema1 <a class="header-anchor" href="#_1-thema1" aria-label="Permalink to &quot;1. Thema1&quot;">​</a></h3><ul><li>Welche Gruppe was getan hat.</li></ul><h3 id="_2-thema2" tabindex="-1">2. Thema2 <a class="header-anchor" href="#_2-thema2" aria-label="Permalink to &quot;2. Thema2&quot;">​</a></h3><ul><li>Wir haben von dem LoRa-WAN Netz besprochen und ein Dokument dazu gelesen, Fremdwörter gelesen und in der Gruppe besprochen.</li><li>Die jeweilgen Gruppen haben zudem weiter Gearbeitet.</li></ul><h3 id="software" tabindex="-1">Software: <a class="header-anchor" href="#software" aria-label="Permalink to &quot;Software:&quot;">​</a></h3><p>Hat das back end und die Website auf deren Geräten zum Laufen gebracht und sie haben sich über unbekannte python imports im Code informiert.</p><h3 id="hardware" tabindex="-1">Hardware: <a class="header-anchor" href="#hardware" aria-label="Permalink to &quot;Hardware:&quot;">​</a></h3><p>Das Hardwareteam hat heute herausgefunden wie die Sendefrequenz geändert werden kann, aber sie wissen nicht wie und wo die Daten hingeschickt werden.</p><h3 id="infrastruktur" tabindex="-1">Infrastruktur: <a class="header-anchor" href="#infrastruktur" aria-label="Permalink to &quot;Infrastruktur:&quot;">​</a></h3><p>Geschaut wie das Gateway funktioniert diesbezüglich müssen aber noch fragen beatwortet werden von IFM.</p><h3 id="projektleitung" tabindex="-1">Projektleitung: <a class="header-anchor" href="#projektleitung" aria-label="Permalink to &quot;Projektleitung:&quot;">​</a></h3><ul><li>Protokoll bearbeitet &amp; hochgeladen.</li><li>Ein Vorlagen Protokoll gemacht damit jeder leichter eins erstellen kann.</li><li>Unbekannte Wörter aus den Dokumenten(LoRa-WAN Infrastruktur) entnommen und &quot;Übersetzt&quot; auf einem extra Dokument.</li></ul><hr><h2 id="ziele-bis-zur-nachsten-sitzung" tabindex="-1">Ziele bis zur nächsten Sitzung: <a class="header-anchor" href="#ziele-bis-zur-nachsten-sitzung" aria-label="Permalink to &quot;Ziele bis zur nächsten Sitzung:&quot;">​</a></h2><h3 id="_1-betrieb-1" tabindex="-1">1. Betrieb: <a class="header-anchor" href="#_1-betrieb-1" aria-label="Permalink to &quot;1. Betrieb:&quot;">​</a></h3><ul><li>Wie der Support vom Gateway Funktioniert.</li></ul><h3 id="_2-hardware-1" tabindex="-1">2. Hardware: <a class="header-anchor" href="#_2-hardware-1" aria-label="Permalink to &quot;2. Hardware:&quot;">​</a></h3><ul><li>Herausfinden wo die Daten hingesendet werden.</li></ul><h3 id="_3-software-1" tabindex="-1">3. Software: <a class="header-anchor" href="#_3-software-1" aria-label="Permalink to &quot;3. Software:&quot;">​</a></h3><ul><li>Denn restlichen Code anschauen, verstehen und gucken was man verbessern kann, bzw was dann ausgetauscht wird.</li></ul><h3 id="_4-projektleitung-1" tabindex="-1">4. Projektleitung: <a class="header-anchor" href="#_4-projektleitung-1" aria-label="Permalink to &quot;4. Projektleitung:&quot;">​</a></h3><ul><li>Email an Ifm senden &amp; das Protokoll schreiben.</li></ul>',38)])])}const c=a(i,[["render",o]]);export{b as __pageData,c as default};
